#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(int argc, char *argv[])
{
    int cur = 0;
    for (int i = 1; i < argc; ++i) {
        char *endptr = NULL;
        long req = strtol(argv[i], &endptr, 10);
        if (*endptr != '\0' || req < 0 || req > INT_MAX) {
            puts("INVALID_FLOOR");
            continue;
        }
        int target = (int)req;
        while (cur != target) {
            if (cur < target) {
                printf("MOVE_UP %d->%d\n", cur, cur + 1);
                ++cur;
            } else {
                printf("MOVE_DOWN %d->%d\n", cur, cur - 1);
                --cur;
            }
        }
        printf("ARRIVE %d\n", cur);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", cur);
    return 0;
}
